import { useCallback, useEffect, useRef, useState } from 'react'
import {
  CYCLE_LENGTH,
  MAX_MINUTES,
  MIN_MINUTES,
  PHASE_LABEL,
  applySettings,
  formatTime,
  initialState,
  parseMinutes,
  remaining,
