  skip,
  tabTitle,
  tick,
  toggle,
  type LogEntry,
  type Settings,
  type TimerState,
} from './timer'
import { loadLog, loadSettings, saveLog, saveSettings } from './storage'
import { chime, primeAudio } from './sound'

const ACCENT = {
  focus: { ring: 'stroke-rose-400', text: 'text-rose-500', dot: 'bg-rose-400', btn: 'bg-rose-500 hover:bg-rose-600' },
  short: { ring: 'stroke-teal-500', text: 'text-teal-600', dot: 'bg-teal-500', btn: 'bg-teal-600 hover:bg-teal-700' },
  long: { ring: 'stroke-indigo-400', text: 'text-indigo-500', dot: 'bg-indigo-400', btn: 'bg-indigo-500 hover:bg-indigo-600' },
} as const

const fmtClock = (ts: number) => new Date(ts).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })

export default function App() {
  const [settings, setSettings] = useState<Settings>(loadSettings)
  const [timer, setTimer] = useState<TimerState>(() => initialState(loadSettings()))
  const [now, setNow] = useState(() => Date.now())
  const [task, setTask] = useState('')
  const [log, setLog] = useState<LogEntry[]>(() => loadLog())
  const [showSettings, setShowSettings] = useState(false)

  // refs so the interval callback always sees the latest values without re-subscribing
  const settingsRef = useRef(settings)
  const taskRef = useRef(task)
  settingsRef.current = settings
  taskRef.current = task

  useEffect(() => saveSettings(settings), [settings])
  useEffect(() => saveLog(log), [log])

  const advance = useCallback(() => {
    const t = Date.now()
    setNow(t)
    setTimer((prev) => {
      const r = tick(prev, settingsRef.current, t)
      if (r.finished) {
        // side effects are deferred out of the updater (it may run twice in StrictMode)
        const finishedFocus = r.finished.phase === 'focus'
        queueMicrotask(() => {
          if (!settingsRef.current.muted) chime()
          if (finishedFocus) {
            setLog((l) => [...l, { id: `${t}-${Math.random().toString(36).slice(2, 7)}`, task: taskRef.current.trim(), finishedAt: t }])
          }
        })
      }
      return r.state
    })
  }, [])

  // timestamp-based: each tick recomputes from endAt, so throttled background timers can't drift
  useEffect(() => {
    if (timer.status !== 'running') return
    const id = setInterval(advance, 250)
    const onVisible = () => document.visibilityState === 'visible' && advance()
    document.addEventListener('visibilitychange', onVisible)
    return () => {
      clearInterval(id)
      document.removeEventListener('visibilitychange', onVisible)
    }
  }, [timer.status, advance])

  const left = remaining(timer, now)
  useEffect(() => {
    document.title = tabTitle(timer, now)
  }, [timer, now])

  const onToggle = useCallback(() => {
    primeAudio()
    const t = Date.now()
    setNow(t)
    setTimer((p) => toggle(p, t))
  }, [])
  const onReset = () => setTimer((p) => reset(p, settings))
  const onSkip = () => setTimer((p) => skip(p, settings))

  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (e.code !== 'Space' || e.repeat) return
      const el = e.target as HTMLElement | null
      const tag = el?.tagName
      if (tag === 'INPUT' || tag === 'TEXTAREA' || tag === 'SELECT' || tag === 'BUTTON') return
      e.preventDefault()
      onToggle()
    }
    window.addEventListener('keydown', onKey)
    return () => window.removeEventListener('keydown', onKey)
  }, [onToggle])

  const updateSettings = (s: Settings) => {
    setSettings(s)
    setTimer((p) => applySettings(p, s))
  }

  const accent = ACCENT[timer.phase]
  const total = settings[timer.phase] * 60_000
  const progress = Math.min(1, Math.max(0, 1 - left / total))
  const R = 130
  const C = 2 * Math.PI * R
  const running = timer.status === 'running'
  const dotsDone = timer.cycle

  return (
    <div className="min-h-screen bg-stone-50 text-stone-800">
      <main className="mx-auto flex w-full max-w-md flex-col gap-6 px-4 py-6 sm:py-10">
        <header className="flex items-center justify-between">
          <h1 className="text-lg font-semibold tracking-tight">Pomodoro</h1>
